#include <iostream>
#include <cstring>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

const int MAXN = 210;
const int INF = 0x3f3f3f3f;

int capacity[MAXN*MAXN*2][MAXN*MAXN*2];
int flow[MAXN*MAXN*2][MAXN*MAXN*2];
int dist[MAXN*MAXN*2], num[MAXN*MAXN*2];
int N, T, source_node, sink_node;

inline int node_id(int r, int c) {
    return (r-1)*N + c;
}

inline bool is_valid(int r, int c) {
    return r >= 1 && r <= N && c >= 1 && c <= N;
}

void connect(int u, int v, int c) {
    capacity[u][v] += c;
}

int push_flow(int u, int bottleneck) {
    if (u == sink_node) return bottleneck;
    int total_pushed = bottleneck, delta, min_dist = N*N*2+2;
    for (int v = 0; v < N*N*2+2; ++v) {
        if (capacity[u][v] - flow[u][v] > 0) {
            if (dist[u] == dist[v] + 1) {
                delta = push_flow(v, min(total_pushed, capacity[u][v] - flow[u][v]));
                flow[u][v] += delta;
                flow[v][u] -= delta;
                total_pushed -= delta;
                if (dist[source_node] == N*N*2+2 || total_pushed == 0) return bottleneck - total_pushed;
            }
            min_dist = min(min_dist, dist[v] + 1);
        }
    }
    if (total_pushed == bottleneck) {
        num[dist[u]]--;
        num[min_dist]++;
        if (num[dist[u]] == 0) dist[source_node] = N*N*2+2;
        dist[u] = min_dist;
    }
    return bottleneck - total_pushed;
}

int compute_maxflow() {
    if (source_node == sink_node) return INF;
    memset(flow, 0, sizeof(flow));
    memset(dist, 0, sizeof(dist));
    memset(num, 0, sizeof(num));
    int result = 0;
    while (dist[source_node] < N*N*2+2) {
        result += push_flow(source_node, INF);
    }
    return result;
}

struct Cell {
    int r, c, d;
};

int time_to_reach[MAXN][MAXN];
bool visited_bfs[MAXN][MAXN];
char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int start_r, start_c;
const int dr[4] = {0,0,-1,1};
const int dc[4] = {-1,1,0,0};

void compute_times() {
    queue<Cell> q;
    q.push({start_r, start_c, 0});
    memset(time_to_reach, 0x7f, sizeof(time_to_reach));
    memset(visited_bfs, 0, sizeof(visited_bfs));
    visited_bfs[start_r][start_c] = true;
    while (!q.empty()) {
        Cell cur = q.front(); q.pop();
        time_to_reach[cur.r][cur.c] = cur.d;
        if (cur.d > T) break;
        for (int k=0; k<4; ++k) {
            int nr = cur.r + dr[k], nc = cur.c + dc[k];
            if (is_valid(nr,nc) && grid1[nr][nc] != 'Y' && !visited_bfs[nr][nc]) {
                Cell next = {nr, nc, cur.d+1};
                visited_bfs[nr][nc] = true;
                q.push(next);
            }
        }
    }
}

void explore_from(int r, int c) {
    queue<Cell> q;
    q.push({r, c, 0});
    memset(visited_bfs, 0, sizeof(visited_bfs));
    visited_bfs[r][c] = true;
    while (!q.empty()) {
        Cell cur = q.front(); q.pop();
        if (cur.d > T) break;
        if (time_to_reach[cur.r][cur.c] < cur.d) continue;
        if (time_to_reach[cur.r][cur.c] == cur.d && (grid2[cur.r][cur.c] < '1' || grid2[cur.r][cur.c] > '9')) continue;
        if (grid2[cur.r][cur.c] >= '1' && grid2[cur.r][cur.c] <= '9') {
            if (cur.r != r || cur.c != c) {
                connect(node_id(r,c), node_id(cur.r,cur.c) + N*N, INF);
            }
            if (time_to_reach[cur.r][cur.c] == cur.d) continue;
        }
        for (int k=0; k<4; ++k) {
            int nr = cur.r + dr[k], nc = cur.c + dc[k];
            if (is_valid(nr,nc) && grid1[nr][nc] != 'Y' && !visited_bfs[nr][nc]) {
                Cell next = {nr, nc, cur.d+1};
                visited_bfs[nr][nc] = true;
                q.push(next);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> N >> T;
    for (int i=1; i<=N; ++i) cin >> (grid1[i]+1);
    for (int i=1; i<=N; ++i) cin >> (grid2[i]+1);

    source_node = 0;
    sink_node = 2*N*N+1;

    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=N; ++j) {
            if (grid1[i][j]>='1' && grid1[i][j]<='9') {
                connect(source_node, node_id(i,j), grid1[i][j]-'0');
            }
            if (grid1[i][j]=='Z') {
                start_r = i; start_c = j;
            }
        }
    }

    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=N; ++j) {
            connect(node_id(i,j), node_id(i,j)+N*N, INF);
            if (grid2[i][j]>='1' && grid2[i][j]<='9') {
                connect(node_id(i,j)+N*N, sink_node, grid2[i][j]-'0');
            }
        }
    }

    compute_times();
    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=N; ++j) {
            if (grid1[i][j]>='1' && grid1[i][j]<='9') {
                explore_from(i,j);
            }
        }
    }

    cout << compute_maxflow() << '\n';
    return 0;
}
